// referenceLandmarks.js
// Machine-readable reference poses for the Learning comparison. The JSON is
// generated by ml/build_reference.py (see README, "Reference data"):
//
//   source "sheet"   landmarks detected on the supplied sheet photo AND
//                    confirmed by the trained classifier (it reads them as that letter)
//   source "dataset" the sheet photo could not be measured reliably, so the pose
//                    comes from a real, correctly-classified sample of the training
//                    dataset. The picture and the comparison target can differ slightly.
//   missing          no usable landmarks (Z): the picture is shown without pose checks.

import data from "./referenceLandmarks.json";

export function getReference(letter) {
  const r = data[letter];
  return r && r.landmarks ? r : null;
}
